// Checkout conversion module - forces paidEvents increment on successful checkout
const fs = require('fs');
const path = require('path');

const REVENUE_FILE = path.join(__dirname, '..', 'data', 'revenue.json');

function recordPaidEvent(amount = 1) {
  let data = { paidEvents: 0, conversionRate: 0, leads: 0 };
  try {
    if (fs.existsSync(REVENUE_FILE)) {
      data = JSON.parse(fs.readFileSync(REVENUE_FILE, 'utf8'));
    }
  } catch (e) {
    // ignore
  }
  data.paidEvents = (data.paidEvents || 0) + amount;
  data.conversionRate = data.leads > 0 ? (data.paidEvents / data.leads) : 0;
  fs.writeFileSync(REVENUE_FILE, JSON.stringify(data, null, 2));
  return data;
}

module.exports = { recordPaidEvent };
